import jwt from 'jsonwebtoken';

export default async function verifyMagicLinkToken(
  { token, magicLinkSecret, sessionSecret, sessionExpiryDays },
  { logging, http }
) {
  // 1. Basic input guards
  if (!token || typeof token !== 'string' || token.trim() === '') {
    http?.status(401);
    return { error: 'Invalid or expired token' };
  }

  if (!magicLinkSecret || !sessionSecret) {
    logging.log('Missing secret configuration');
    http?.status(500);
    return { error: 'Server configuration error' };
  }

  // 2. Verify magic link JWT — signature + expiry checked by jsonwebtoken
  let claims;
  try {
    claims = jwt.verify(token.trim(), magicLinkSecret, { algorithms: ['HS256'] });
  } catch (err) {
    // TokenExpiredError, JsonWebTokenError, NotBeforeError all land here
    logging.log('JWT verification failed:', err.name, err.message);
    http?.status(401);
    return { error: 'Invalid or expired token' };
  }

  // 3. Extract and validate email claim
  const email = claims?.email;
  if (!email || typeof email !== 'string' || !email.includes('@')) {
    logging.log('JWT missing valid email claim:', claims);
    http?.status(401);
    return { error: 'Invalid or expired token' };
  }

  logging.log('Magic link verified for:', email);

  // 4. Issue session JWT — 30 days by default
  const expiryDays = (typeof sessionExpiryDays === 'number' && sessionExpiryDays > 0)
    ? sessionExpiryDays
    : 30;

  const now = Math.floor(Date.now() / 1000);
  const sessionPayload = {
    email,
    exp: now + expiryDays * 24 * 60 * 60,
    iat: now
  };

  let sessionToken;
  try {
    sessionToken = jwt.sign(sessionPayload, sessionSecret, { algorithm: 'HS256' });
  } catch (err) {
    logging.log('Failed to sign session JWT:', err.message);
    http?.status(500);
    return { error: 'Server configuration error' };
  }

  logging.log('Session token issued, expiry:', expiryDays, 'days');

  // 5. Return email + session token
  return { email, sessionToken };
}

